@Composable
fun PasswordScreen(correctPassword: String, onSuccess: () -> Unit) {
    var passwordInput by remember { mutableStateOf("") }
    var errorMessage by remember { mutableStateOf(false) }
    val focusRequester = remember { FocusRequester() }
    val keyboardController = LocalSoftwareKeyboardController.current

    LaunchedEffect(Unit) {
        try {
            focusRequester.requestFocus()
            keyboardController?.show()
        } catch (_: Exception) {}
    }

    fun handleAuthenticate(input: String) {
        if (input == correctPassword) {
            onSuccess()
        } else {
            errorMessage = true
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .verticalScroll(rememberScrollState())
            .padding(24.dp),
        verticalArrangement = Arrangement.Center,
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Text("🔒 パスワード認証", style = MaterialTheme.typography.headlineMedium, fontWeight = FontWeight.Bold)
        Spacer(modifier = Modifier.height(8.dp))
        Text("このアプリを利用するにはパスワードが必要です", style = MaterialTheme.typography.bodyMedium, color = Color.Gray)
        Spacer(modifier = Modifier.height(24.dp))

        OutlinedTextField(
            value = passwordInput,
            onValueChange = { input ->
                passwordInput = input
                errorMessage = false
                if (input.length == correctPassword.length && input == correctPassword) {
                    handleAuthenticate(input)
                }
            },
            label = { Text("パスワードを入力") },
            visualTransformation = PasswordVisualTransformation(),
            keyboardOptions = KeyboardOptions(
                keyboardType = KeyboardType.NumberPassword,
                imeAction = ImeAction.Done
            ),
            keyboardActions = KeyboardActions(onDone = {
                handleAuthenticate(passwordInput)
            }),
            modifier = Modifier
                .widthIn(max = 360.dp)
                .fillMaxWidth()
                .focusRequester(focusRequester),
            singleLine = true
        )

        if (errorMessage) {
            Spacer(modifier = Modifier.height(8.dp))
            Text("パスワードが違います", color = MaterialTheme.colorScheme.error, fontWeight = FontWeight.SemiBold)
        }

        Spacer(modifier = Modifier.height(24.dp))

        Text("画面上のボタンでも入力できます:", style = MaterialTheme.typography.labelMedium, color = Color.Gray)
        Spacer(modifier = Modifier.height(12.dp))

        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(10.dp),
            modifier = Modifier.widthIn(max = 320.dp)
        ) {
            val buttons = listOf(
                listOf("1", "2", "3"),
                listOf("4", "5", "6"),
                listOf("7", "8", "9"),
                listOf("C", "0", "⌫")
            )

            for (row in buttons) {
                Row(
                    horizontalArrangement = Arrangement.spacedBy(12.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    for (label in row) {
                        OutlinedButton(
                            onClick = {
                                errorMessage = false
                                try {
                                    focusRequester.requestFocus()
                                    keyboardController?.show()
                                } catch (_: Exception) {}

                                when (label) {
                                    "C" -> passwordInput = ""
                                    "⌫" -> if (passwordInput.isNotEmpty()) passwordInput = passwordInput.dropLast(1)
                                    else -> {
                                        val newInput = passwordInput + label
                                        passwordInput = newInput
                                        if (newInput.length == correctPassword.length && newInput == correctPassword) {
                                            handleAuthenticate(newInput)
                                        }
                                    }
                                }
                            },
                            modifier = Modifier
                                .weight(1f)
                                .height(54.dp),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Text(label, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold)
                        }
                    }
                }
            }
        }

        Spacer(modifier = Modifier.height(24.dp))

        Button(
            onClick = { handleAuthenticate(passwordInput) },
            modifier = Modifier
                .widthIn(max = 360.dp)
                .fillMaxWidth()
                .height(56.dp)
        ) {
            Text("認証して進む", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
        }
    }
}

// 2. メイン画面
@Composable
fun VocabAppMainScreen() {
    val jsonFormat = remember { Json { ignoreUnknownKeys = true } }

    var categoryFiles by remember {
        mutableStateOf(
            try {
                val saved = localStorage.getItem("category_files")
                if (saved != null) jsonFormat.decodeFromString<Map<String, List<String>>>(saved)
                else mapOf("一般" to listOf("デフォルト"))
            } catch (e: Exception) {
                mapOf("一般" to listOf("デフォルト"))
            }
        )
    }
    LaunchedEffect(categoryFiles) {
        try { localStorage.setItem("category_files", jsonFormat.encodeToString(categoryFiles)) } catch (_: Exception) {}
    }

    val reindexFileWords: (List<Word>, String, String) -> List<Word> = { list, cat, file ->
        var idCounter = 1
        list.map { w ->
            if (w.category == cat && w.fileName == file) w.copy(id = idCounter++) else w
        }
    }

    var wordList by remember {
        mutableStateOf(
            try {
                val saved = localStorage.getItem("word_list")
                if (saved != null) {
                    jsonFormat.decodeFromString<List<Word>>(saved)
                } else {
                    listOf(
                        Word(1, "apple", "りんご", "一般", "デフォルト"),
                        Word(2, "banana", "バナナ", "一般", "デフォルト")
                    )
                }
            } catch (e: Exception) {
                listOf(Word(1, "apple", "りんご", "一般", "デフォルト"))
            }
        )
    }
    LaunchedEffect(wordList) {
        try { localStorage.setItem("word_list", jsonFormat.encodeToString(wordList)) } catch (_: Exception) {}
    }

    var wrongCounts by remember {
        mutableStateOf(
            try {
                val saved = localStorage.getItem("wrong_counts")
                if (saved != null) jsonFormat.decodeFromString<Map<String, Int>>(saved) else emptyMap()
            } catch (e: Exception) { emptyMap() }
        )
    }
    LaunchedEffect(wrongCounts) {
        try { localStorage.setItem("wrong_counts", jsonFormat.encodeToString(wrongCounts)) } catch (_: Exception) {}
    }

    var correctCounts by remember {
        mutableStateOf(
            try {
                val saved = localStorage.getItem("correct_counts")
                if (saved != null) jsonFormat.decodeFromString<Map<String, Int>>(saved) else emptyMap()
            } catch (e: Exception) { emptyMap() }
        )
    }
    LaunchedEffect(correctCounts) {
        try { localStorage.setItem("correct_counts", jsonFormat.encodeToString(correctCounts)) } catch (_: Exception) {}
    }

    var lastWrongTimes by remember {
        mutableStateOf(
            try {
                val saved = localStorage.getItem("last_wrong_times")
                if (saved != null) jsonFormat.decodeFromString<Map<String, Long>>(saved) else emptyMap()
            } catch (e: Exception) { emptyMap() }
        )
    }
    LaunchedEffect(lastWrongTimes) {
        try { localStorage.setItem("last_wrong_times", jsonFormat.encodeToString(lastWrongTimes)) } catch (_: Exception) {}
    }

    // 💡 ローカル時間（端末のタイムゾーン）で正確な YYYYMMDD を取得するよう修正
    val getTodayStr: () -> String = {
        js("""
            (function() {
                const d = new Date();
                const y = d.getFullYear();
                const m = String(d.getMonth() + 1).padStart(2, '0');
                const day = String(d.getDate()).padStart(2, '0');
                return '' + y + m + day;
            })()
        """) as String
    }
    val todayStr = remember { getTodayStr() }

    var todayTotal by remember {
        mutableStateOf(
            try {
                val savedDate = localStorage.getItem("today_date")
                if (savedDate == todayStr) localStorage.getItem("today_total")?.toIntOrNull() ?: 0 else 0
            } catch (e: Exception) { 0 }
        )
    }

    var todayCorrect by remember {
        mutableStateOf(
            try {
                val savedDate = localStorage.getItem("today_date")
                if (savedDate == todayStr) localStorage.getItem("today_correct")?.toIntOrNull() ?: 0 else 0
            } catch (e: Exception) { 0 }
        )
    }

    var currentStreak by remember {
        mutableStateOf(
            try { localStorage.getItem("current_streak")?.toIntOrNull() ?: 1 } catch (e: Exception) { 1 }
        )
    }

    var weeklyHistory by remember {
        mutableStateOf(
            try {
                val saved = localStorage.getItem("weekly_history")
                if (saved != null) jsonFormat.decodeFromString<Map<String, Int>>(saved) else mapOf(todayStr to 0)
            } catch (e: Exception) { mapOf(todayStr to 0) }
        )
    }
    LaunchedEffect(weeklyHistory) {
        try { localStorage.setItem("weekly_history", jsonFormat.encodeToString(weeklyHistory)) } catch (_: Exception) {}
    }

    LaunchedEffect(Unit) {
        val savedDate = localStorage.getItem("today_date")
        if (savedDate != todayStr) {
            localStorage.setItem("today_date", todayStr)
            localStorage.setItem("today_total", "0")
            localStorage.setItem("today_correct", "0")
            todayTotal = 0
            todayCorrect = 0
            if (!weeklyHistory.containsKey(todayStr)) {
                weeklyHistory = weeklyHistory + (todayStr to 0)
            }
        }
    }

    val speakWord: (String) -> Unit = { text ->
        js("""
            if ('speechSynthesis' in window) {
                window.speechSynthesis.cancel();
                const utterance = new SpeechSynthesisUtterance(text);
                utterance.lang = 'en-US';
                window.speechSynthesis.speak(utterance);
            }
        """)
    }

    val updateStudyStats: (Boolean) -> Unit = { isCorrect ->
        val currentDay = getTodayStr()
        val savedDate = localStorage.getItem("today_date")
        if (savedDate != currentDay) {
            todayTotal = 0
            todayCorrect = 0
            localStorage.setItem("today_date", currentDay)
        }

        todayTotal++
        if (isCorrect) todayCorrect++

        localStorage.setItem("today_total", todayTotal.toString())
        localStorage.setItem("today_correct", todayCorrect.toString())

        val currentCount = weeklyHistory[currentDay] ?: 0
        weeklyHistory = weeklyHistory + (currentDay to (currentCount + 1))

        val lastStudy = localStorage.getItem("last_study_date") ?: ""
        if (lastStudy != currentDay) {
            val isConsecutive = js("""
                (function() {
                    if (!lastStudy) return false;
                    const last = new Date(lastStudy.slice(0,4), lastStudy.slice(4,6)-1, lastStudy.slice(6,8));
                    const curr = new Date(currentDay.slice(0,4), currentDay.slice(4,6)-1, currentDay.slice(6,8));
                    return (curr - last) / (1000 * 60 * 60 * 24) === 1;
                })()
            """) as Boolean

            val isSameDay = (lastStudy == currentDay)
            if (!isSameDay) {
                if (isConsecutive) {
                    currentStreak++
                } else if (lastStudy.isEmpty()) {
                    currentStreak = 1
                } else {
                    val diffDays = js("""
                        (function() {
                            const last = new Date(lastStudy.slice(0,4), lastStudy.slice(4,6)-1, lastStudy.slice(6,8));
                            const curr = new Date(currentDay.slice(0,4), currentDay.slice(4,6)-1, currentDay.slice(6,8));
                            return (curr - last) / (1000 * 60 * 60 * 24);
                        })()
                    """) as Double
                    if (diffDays > 1.0) currentStreak = 1
                }
                localStorage.setItem("last_study_date", currentDay)
                localStorage.setItem("current_streak", currentStreak.toString())
            }
        }
    }

    val incrementWrongCount: (Word) -> Unit = { word ->
        val key = "${word.category}_${word.fileName}_${word.id}"
        wrongCounts = wrongCounts + (key to ((wrongCounts[key] ?: 0) + 1))
        val now = (js("Date.now()") as Number).toLong()
        lastWrongTimes = lastWrongTimes + (key to now)
        updateStudyStats(false)
    }

    val recordCorrectAnswer: (Word) -> Unit = { word ->
        val key = "${word.category}_${word.fileName}_${word.id}"
        correctCounts = correctCounts + (key to ((correctCounts[key] ?: 0) + 1))
        updateStudyStats(true)
    }

    val undoWrongAnswer: (Word) -> Unit = { word ->
        val key = "${word.category}_${word.fileName}_${word.id}"
        val current = wrongCounts[key] ?: 0
        if (current > 1) {
            wrongCounts = wrongCounts + (key to (current - 1))
        } else {
            wrongCounts = wrongCounts - key
        }
        if (todayTotal > 0) {
            todayTotal--
            localStorage.setItem("today_total", todayTotal.toString())
        }
        val currentDay = getTodayStr()
        val graphCount = weeklyHistory[currentDay] ?: 0
        if (graphCount > 0) {
            weeklyHistory = weeklyHistory + (currentDay to (graphCount - 1))
        }
    }

    val undoCorrectAnswer: (Word) -> Unit = { word ->
        val key = "${word.category}_${word.fileName}_${word.id}"
        val current = correctCounts[key] ?: 0
        if (current > 1) {
            correctCounts = correctCounts + (key to (current - 1))
        } else {
            correctCounts = correctCounts - key
        }
        if (todayTotal > 0) {
            todayTotal--
            localStorage.setItem("today_total", todayTotal.toString())
        }
        if (todayCorrect > 0) {
            todayCorrect--
            localStorage.setItem("today_correct", todayCorrect.toString())
        }
        val currentDay = getTodayStr()
        val graphCount = weeklyHistory[currentDay] ?: 0
        if (graphCount > 0) {
            weeklyHistory = weeklyHistory + (currentDay to (graphCount - 1))
        }
    }

    val addWord: (String, String, String, String) -> Unit = { english, japanese, category, fileName ->
        val files = categoryFiles[category] ?: listOf("デフォルト")
        val targetFile = if (files.contains(fileName)) fileName else {
            categoryFiles = categoryFiles + (category to (files + fileName))
            fileName
        }
        val catWords = wordList.filter { it.category == category && it.fileName == targetFile }
        val tempId = catWords.size + 1
        val newWord = Word(tempId, english, japanese, category, targetFile)
        val addedList = wordList + newWord
        wordList = reindexFileWords(addedList, category, targetFile)
    }

    val addMultipleWords: (String, String, List<Pair<String, String>>) -> Unit = { category, fileName, pairs ->
        val files = categoryFiles[category] ?: listOf("デフォルト")
        val targetFile = if (files.contains(fileName)) fileName else {
            categoryFiles = categoryFiles + (category to (files + fileName))
            fileName
        }
        val currentList = wordList
        val catWords = currentList.filter { it.category == category && it.fileName == targetFile }
        var nextId = catWords.size + 1

        val newWords = pairs.map { (eng, jap) ->
            Word(id = nextId++, english = eng, japanese = jap, category = category, fileName = targetFile)
        }
        val addedList = currentList + newWords
        wordList = reindexFileWords(addedList, category, targetFile)
    }

    val updateWord: (Int, String, String, String, String) -> Unit = { id, english, japanese, category, fileName ->
        wordList = wordList.map { word ->
            if (word.id == id && word.category == category && word.fileName == fileName) {
                word.copy(english = english, japanese = japanese)
            } else {
                word
            }
        }
    }

    val deleteMultipleWords: (List<Int>, String, String) -> Unit = { ids, category, fileName ->
        val filtered = wordList.filterNot { it.category == category && it.fileName == fileName && ids.contains(it.id) }
        wordList = reindexFileWords(filtered, category, fileName)
    }

    val addFile: (String, String) -> Boolean = { category, fileName ->
        val trimmed = fileName.trim()
        val files = categoryFiles[category] ?: listOf("デフォルト")
        if (trimmed.isNotBlank() && !files.contains(trimmed)) {
            categoryFiles = categoryFiles + (category to (files + trimmed))
            true
        } else {
            false
        }
    }

    val renameFile: (String, String, String) -> Boolean = { category, oldName, newName ->
        val trimmed = newName.trim()
        val files = categoryFiles[category] ?: listOf("デフォルト")
        if (trimmed.isNotBlank() && !files.contains(trimmed)) {
            categoryFiles = categoryFiles + (category to files.map { if (it == oldName) trimmed else it })
            wordList = wordList.map { if (it.category == category && it.fileName == oldName) it.copy(fileName = trimmed) else it }
            true
        } else {
            false
        }
    }

    val deleteFile: (String, String) -> Unit = { category, fileName ->
        val files = categoryFiles[category] ?: listOf("デフォルト")
        if (files.size > 1) {
            categoryFiles = categoryFiles + (category to files.filter { it != fileName })
            wordList = wordList.filterNot { it.category == category && it.fileName == fileName }
        }
    }

    val restoreBackupData: (AppBackup) -> Unit = { backup ->
        categoryFiles = backup.categoryFiles
        wordList = backup.wordList
        wrongCounts = backup.wrongCounts
        correctCounts = backup.correctCounts
        lastWrongTimes = backup.lastWrongTimes
        weeklyHistory = backup.weeklyHistory
        currentStreak = backup.currentStreak
        todayTotal = backup.todayTotal
        todayCorrect = backup.todayCorrect

        try {
            localStorage.setItem("category_files", jsonFormat.encodeToString(backup.categoryFiles))
            localStorage.setItem("word_list", jsonFormat.encodeToString(backup.wordList))
            localStorage.setItem("wrong_counts", jsonFormat.encodeToString(backup.wrongCounts))
            localStorage.setItem("correct_counts", jsonFormat.encodeToString(backup.correctCounts))
            localStorage.setItem("last_wrong_times", jsonFormat.encodeToString(backup.lastWrongTimes))
            localStorage.setItem("weekly_history", jsonFormat.encodeToString(backup.weeklyHistory))
            localStorage.setItem("current_streak", backup.currentStreak.toString())
            localStorage.setItem("today_total", backup.todayTotal.toString())
            localStorage.setItem("today_correct", backup.todayCorrect.toString())
            localStorage.setItem("today_date", backup.todayDate)
        } catch (_: Exception) {}
    }

    var currentScreen by remember { mutableStateOf("home") }
    var selectedCategory by remember { mutableStateOf("一般") }
    var selectedCategoryName by remember { mutableStateOf("一般") }
    var selectedFileName by remember { mutableStateOf("デフォルト") }
    var testStartId by remember { mutableStateOf(1) }
    var testEndId by remember { mutableStateOf(100) }
    var isShuffled by remember { mutableStateOf(false) }
    var testScopeType by remember { mutableStateOf("range") }
    var testMode by remember { mutableStateOf("card") }
    var testSessionId by remember { mutableStateOf(0) }

    when (currentScreen) {
        "home" -> HomeScreen(
            todayTotal = todayTotal,
            todayCorrect = todayCorrect,
            streakCount = currentStreak,
            weeklyHistory = weeklyHistory,
            onGoToTestSetup = { currentScreen = "setup" },
            onNavigateToAdd = { currentScreen = "add" },
            onNavigateToList = { currentScreen = "list" }
        )
        "setup" -> TestSetupScreen(
            wordList = wordList,
            categoryFiles = categoryFiles,
            onStartTest = { category, fileName, start, end, shuffled, scopeType, mode ->
                selectedCategory = category
                selectedCategoryName = category
                selectedFileName = fileName
                testStartId = start
                testEndId = end
                isShuffled = shuffled
                testScopeType = scopeType
                testMode = mode
                testSessionId++
                currentScreen = "test"
            },
            onBack = { currentScreen = "home" }
        )
        "test" -> TestScreen(
            wordList = wordList,
            wrongCounts = wrongCounts,
            lastWrongTimes = lastWrongTimes,
            category = selectedCategory,
            fileName = selectedFileName,
            startId = testStartId,
            endId = testEndId,
            isShuffled = isShuffled,
            testScopeType = testScopeType,
            testMode = testMode,
            testSessionId = testSessionId,
            onWrongAnswer = incrementWrongCount,
            onCorrectAnswer = recordCorrectAnswer,
            onUndoWrongAnswer = undoWrongAnswer,
            onUndoCorrectAnswer = undoCorrectAnswer,
            onSpeak = speakWord,
            onBack = { currentScreen = "setup" }
        )
        "add" -> AddWordScreen(
            categoryFiles = categoryFiles,
            onAddWord = { english, japanese, category, fileName ->
                addWord(english, japanese, category, fileName)
                currentScreen = "home"
            },
            onAddFile = addFile,
            onBack = { currentScreen = "home" }
        )
        "list" -> WordListScreen(
            wordList = wordList,
            categoryFiles = categoryFiles,
            wrongCounts = wrongCounts,
            correctCounts = correctCounts,
            lastWrongTimes = lastWrongTimes,
            weeklyHistory = weeklyHistory,
            currentStreak = currentStreak,
            todayTotal = todayTotal,
            todayCorrect = todayCorrect,
            todayDate = todayStr,
            onUpdateWord = updateWord,
            onDeleteMultipleWords = deleteMultipleWords,
            onAddFile = addFile,
            onRenameFile = renameFile,
            onDeleteFile = deleteFile,
            onAddMultipleWords = addMultipleWords,
            onRestoreBackup = restoreBackupData,
            onSpeak = speakWord,
            onBack = { currentScreen = "home" }
        )
    }
}

fun exportFullBackupToJson(backupData: AppBackup, jsonFormat: Json) {
    val jsonStr = jsonFormat.encodeToString(backupData)
    js("""
        (function(content) {
            const blob = new Blob([content], { type: 'application/json;charset=utf-8;' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = 'vocab_app_full_backup_' + new Date().toISOString().slice(0, 10) + '.json';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        })(jsonStr)
    """)
}

fun importFullBackupFromJson(onLoaded: (String) -> Unit) {
    val input = document.createElement("input") as HTMLInputElement
    input.type = "file"
    input.accept = ".json"
    input.onchange = {
        val file = input.files?.item(0)
        if (file != null) {
            val reader = FileReader()
            reader.onload = { _ ->
                val text = reader.result as? String ?: ""
                if (text.isNotBlank()) onLoaded(text)
            }
            reader.readAsText(file)
        }
    }
    input.click()
}

fun exportWordsToCsv(fileName: String, words: List<Word>) {
    val csvLines = mutableListOf("English,Japanese")
    for (w in words) {
        val eng = w.english.replace("\"", "\"\"")
        val jap = w.japanese.replace("\"", "\"\"")
        csvLines.add("\"$eng\",\"$jap\"")
    }
    val csvContent = csvLines.joinToString("\n")

    js("""
        (function(content, name) {
            const blob = new Blob([content], { type: 'text/csv;charset=utf-8;' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = name + '.csv';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        })(csvContent, fileName)
    """)
}

@Composable
fun WeeklyProgressChart(weeklyHistory: Map<String, Int>) {
    Card(
        modifier = Modifier.fillMaxWidth(),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant)
    ) {
        Column(modifier = Modifier.fillMaxWidth().padding(16.dp)) {
            Text("📈 週間学習グラフ（直近7日間）", style = MaterialTheme.typography.titleMedium, color = MaterialTheme.colorScheme.primary)
            Spacer(modifier = Modifier.height(16.dp))

            val recentDays = remember(weeklyHistory) {
                val list = mutableListOf<String>()
                for (i in 6 downTo 0) {
                    val dayStr = js("""
                        (function() {
                            const d = new Date();
                            d.setDate(d.getDate() - i);
                            const y = d.getFullYear();
                            const m = String(d.getMonth() + 1).padStart(2, '0');
                            const day = String(d.getDate()).padStart(2, '0');
                            return '' + y + m + day;
                        })()
                    """) as String
                    list.add(dayStr)
                }
                list
            }

            val maxVal = recentDays.maxOfOrNull { weeklyHistory[it] ?: 0 }?.coerceAtLeast(5) ?: 5

            Row(
                modifier = Modifier.fillMaxWidth().height(140.dp),
                horizontalArrangement = Arrangement.SpaceAround,
                verticalAlignment = Alignment.Bottom
            ) {
                recentDays.forEach { dayStr ->
                    val count = weeklyHistory[dayStr] ?: 0
                    val month = dayStr.substring(4, 6).toInt()
                    val day = dayStr.substring(6, 8).toInt()
                    val label = "$month/$day"

                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Bottom,
                        modifier = Modifier.weight(1f).fillMaxHeight()
                    ) {
                        Text("$count", style = MaterialTheme.typography.bodySmall)
                        Spacer(modifier = Modifier.height(4.dp))

                        val maxHeightDp = 65.dp
                        val fraction = if (maxVal > 0) (count.toFloat() / maxVal).coerceIn(0.08f, 1f) else 0.08f
                        val barHeight = maxHeightDp * fraction

                        Box(
                            modifier = Modifier
                                .width(16.dp)
                                .height(barHeight)
                                .background(MaterialTheme.colorScheme.primary, shape = MaterialTheme.shapes.small)
                        )
                        Spacer(modifier = Modifier.height(6.dp))
                        Text(label, style = MaterialTheme.typography.labelSmall)
                    }
                }
            }
        }
    }
}

