fun launchExcelImport(category: String, onImported: (String, List<Pair<String, String>>) -> Unit) {
    val input = document.createElement("input") as HTMLInputElement
    input.type = "file"
    input.accept = ".xlsx, .xls, .csv"
    input.onchange = {
        val file = input.files?.item(0)
        if (file != null) {
            val fileNameWithoutExt = file.name.substringBeforeLast(".")
            val reader = FileReader()
            if (file.name.endsWith(".csv", ignoreCase = true)) {
                reader.onload = { _ ->
                    val text = reader.result as? String ?: ""
                    val words = mutableListOf<Pair<String, String>>()
                    for (line in text.lines()) {
                        val parts = line.split(",")
                        if (parts.size >= 2) {
                            val eng = parts[0].trim().removeSurrounding("\"")
                            val jap = parts[1].trim().removeSurrounding("\"")
                            if (eng.isNotBlank() && jap.isNotBlank() && eng.lowercase() != "english" && eng != "英語") {
                                words.add(Pair(eng, jap))
                            }
                        }
                    }
                    if (words.isNotEmpty()) {
                        onImported(fileNameWithoutExt, words)
                    }
                }
                reader.readAsText(file)
            } else {
                reader.onload = { _ ->
                    val arrayBuffer = reader.result
                    try {
                        val data = js("new Uint8Array(arrayBuffer)")
                        val workbook = js("XLSX.read(data, {type: 'array'})")
                        val firstSheetName = workbook.SheetNames[0]
                        val worksheet = workbook.Sheets[firstSheetName]
                        val json = js("XLSX.utils.sheet_to_json(worksheet, {header: 1})")

                        val words = mutableListOf<Pair<String, String>>()
                        val length = js("json.length") as Int
                        for (i in 0 until length) {
                            val row = js("json[i]")
                            if (row != null && js("row.length") >= 2) {
                                val eng = js("row[0]")?.toString()?.trim() ?: ""
                                val jap = js("row[1]")?.toString()?.trim() ?: ""
                                if (eng.isNotBlank() && jap.isNotBlank() && eng.lowercase() != "english" && eng != "英語") {
                                    words.add(Pair(eng, jap))
                                }
                            }
                        }
                        if (words.isNotEmpty()) {
                            onImported(fileNameWithoutExt, words)
                        }
                    } catch (e: Exception) {
                        println("Excel parse error: $e")
                    }
                }
                reader.readAsArrayBuffer(file)
            }
        }
    }
    input.click()
}

@Composable
fun WordListScreen(
    wordList: List<Word>,
    categoryFiles: Map<String, List<String>>,
    wrongCounts: Map<String, Int>,
    correctCounts: Map<String, Int>,
    lastWrongTimes: Map<String, Long>,
    weeklyHistory: Map<String, Int>,
    currentStreak: Int,
    todayTotal: Int,
    todayCorrect: Int,
    todayDate: String,
    onUpdateWord: (Int, String, String, String, String) -> Unit,
    onDeleteMultipleWords: (List<Int>, String, String) -> Unit,
    onAddFile: (String, String) -> Boolean,
    onRenameFile: (String, String, String) -> Boolean,
    onDeleteFile: (String, String) -> Unit,
    onAddMultipleWords: (String, String, List<Pair<String, String>>) -> Unit,
    onRestoreBackup: (AppBackup) -> Unit,
    onSpeak: (String) -> Unit,
    onBack: () -> Unit
) {
    val focusManager = LocalFocusManager.current
    val jsonFormat = remember { Json { ignoreUnknownKeys = true } }
    val selectedCategory = "一般"
    val files = categoryFiles[selectedCategory] ?: listOf("デフォルト")
    var selectedFileName by remember { mutableStateOf(files.firstOrNull() ?: "デフォルト") }
    var searchQuery by remember { mutableStateOf("") }
    var showSearch by remember { mutableStateOf(false) }
    var selectedRange by remember { mutableStateOf("すべて") }
    var sortOrder by remember { mutableStateOf("default") }

    var editingWord by remember { mutableStateOf<Word?>(null) }
    var editEnglish by remember { mutableStateOf("") }
    var editJapanese by remember { mutableStateOf("") }

    var showFileManageDialog by remember { mutableStateOf(false) }

    val fileWords = remember(wordList, selectedFileName) {
        wordList.filter { it.category == selectedCategory && it.fileName == selectedFileName }
    }

    val ranges = remember(fileWords) {
        val size = fileWords.size
        if (size <= 100) {
            listOf("すべて")
        } else {
            val list = mutableListOf<String>()
            var start = 1
            while (start <= size) {
                val end = minOf(start + 99, size)
                list.add("$start-$end")
                start += 100
            }
            listOf("すべて") + list
        }
    }

    LaunchedEffect(selectedFileName, ranges) {
        if (!ranges.contains(selectedRange)) selectedRange = "すべて"
    }

    val filteredWords = remember(fileWords, searchQuery, selectedRange, sortOrder, wrongCounts, correctCounts) {
        val base = fileWords.filter { word ->
            val matchRange = if (selectedRange == "すべて") true else {
                val parts = selectedRange.split("-")
                val start = parts[0].toIntOrNull() ?: 1
                val end = parts[1].toIntOrNull() ?: 100
                word.id in start..end
            }
            val matchSearch = if (searchQuery.isBlank()) true else {
                word.english.contains(searchQuery, ignoreCase = true) || word.japanese.contains(searchQuery)
            }
            matchRange && matchSearch
        }

        when (sortOrder) {
            "accuracy_asc" -> base.sortedWith(compareBy { word ->
                val key = "${word.category}_${word.fileName}_${word.id}"
                val cor = correctCounts[key] ?: 0
                val wro = wrongCounts[key] ?: 0
                val tot = cor + wro
                if (tot == 0) 1.0 else cor.toDouble() / tot
            })
            "accuracy_desc" -> base.sortedWith(compareByDescending { word ->
                val key = "${word.category}_${word.fileName}_${word.id}"
                val cor = correctCounts[key] ?: 0
                val wro = wrongCounts[key] ?: 0
                val tot = cor + wro
                if (tot == 0) -1.0 else cor.toDouble() / tot
            })
            "wrong_desc" -> base.sortedByDescending { word ->
                val key = "${word.category}_${word.fileName}_${word.id}"
                wrongCounts[key] ?: 0
            }
            else -> base
        }
    }

    if (editingWord != null) {
        AlertDialog(
            onDismissRequest = { editingWord = null },
            title = { Text("単語の編集") },
            text = {
                Column {
                    OutlinedTextField(
                        value = editEnglish,
                        onValueChange = { editEnglish = it },
                        label = { Text("英語") },
                        keyboardOptions = KeyboardOptions(imeAction = ImeAction.Next),
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true
                    )
                    Spacer(modifier = Modifier.height(8.dp))
                    OutlinedTextField(
                        value = editJapanese,
                        onValueChange = { editJapanese = it },
                        label = { Text("日本語") },
                        keyboardOptions = KeyboardOptions(imeAction = ImeAction.Done),
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true
                    )
                }
            },
            confirmButton = {
                Button(onClick = {
                    editingWord?.let { word ->
                        onUpdateWord(word.id, editEnglish, editJapanese, selectedCategory, selectedFileName)
                    }
                    editingWord = null
                }) { Text("更新") }
            },
            dismissButton = { OutlinedButton(onClick = { editingWord = null }) { Text("キャンセル") } }
        )
    }

    if (showFileManageDialog) {
        var newFileToAdd by remember { mutableStateOf("") }
        var renameInputs by remember { mutableStateOf(files.associateWith { it }) }

        LaunchedEffect(files) {
            renameInputs = files.associateWith { it }
        }

        AlertDialog(
            onDismissRequest = { showFileManageDialog = false },
            title = { Text("📁 ファイル・データ管理") },
            text = {
                Column(
                    modifier = Modifier.fillMaxWidth().heightIn(max = 450.dp).verticalScroll(rememberScrollState()),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Button(
                        onClick = {
                            launchExcelImport(selectedCategory) { importedFileName, importedWords ->
                                onAddMultipleWords(selectedCategory, importedFileName, importedWords)
                                selectedFileName = importedFileName
                                showFileManageDialog = false
                            }
                        },
                        modifier = Modifier.fillMaxWidth(),
                        colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.tertiaryContainer, contentColor = MaterialTheme.colorScheme.onTertiaryContainer)
                    ) {
                        Text("📊 エクセル / CSVファイルから一括インポート")
                    }

                    Button(
                        onClick = { exportWordsToCsv(selectedFileName, fileWords) },
                        modifier = Modifier.fillMaxWidth(),
                        colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.secondaryContainer, contentColor = MaterialTheme.colorScheme.onSecondaryContainer)
                    ) {
                        Text("📤 この単語帳をCSVでエクスポート（単語の共有）")
                    }

                    HorizontalDivider()

                    Text("🔄 機種変更・バックアップ", style = MaterialTheme.typography.titleSmall, color = MaterialTheme.colorScheme.primary)

                    Button(
                        onClick = {
                            val backup = AppBackup(
                                categoryFiles = categoryFiles,
                                wordList = wordList,
                                wrongCounts = wrongCounts,
                                correctCounts = correctCounts,
                                lastWrongTimes = lastWrongTimes,
                                weeklyHistory = weeklyHistory,
                                currentStreak = currentStreak,
                                todayDate = todayDate,
                                todayTotal = todayTotal,
                                todayCorrect = todayCorrect
                            )
                            exportFullBackupToJson(backup, jsonFormat)
                        },
                        modifier = Modifier.fillMaxWidth(),
                        colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primaryContainer, contentColor = MaterialTheme.colorScheme.onPrimaryContainer)
                    ) {
                        Text("📦 全データ（成績含む）をJSONでバックアップ")
                    }

                    Button(
                        onClick = {
                            importFullBackupFromJson { jsonText ->
                                try {
                                    val backup = jsonFormat.decodeFromString<AppBackup>(jsonText)
                                    onRestoreBackup(backup)
                                    showFileManageDialog = false
                                } catch (e: Exception) {
                                    println("Backup restore error: $e")
                                }
                            }
                        },
                        modifier = Modifier.fillMaxWidth(),
                        colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.errorContainer, contentColor = MaterialTheme.colorScheme.onErrorContainer)
                    ) {
                        Text("📥 バックアップファイルを復元（インポート）")
                    }

                    HorizontalDivider()

                    Text("新しいファイルを手動追加", style = MaterialTheme.typography.titleSmall, color = MaterialTheme.colorScheme.primary)
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(4.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                    OutlinedTextField(
                        value = newFileToAdd,
                        onValueChange = { newFileToAdd = it },
                        label = { Text("ファイル名") },
                        keyboardOptions = KeyboardOptions(imeAction = ImeAction.Done),
                        modifier = Modifier.weight(1f),
                        singleLine = true
                    )
                        Button(onClick = {
                            if (onAddFile(selectedCategory, newFileToAdd)) {
                                selectedFileName = newFileToAdd.trim()
                                newFileToAdd = ""
                            }
                        }) { Text("追加") }
                    }

                    HorizontalDivider()

                    Text("既存のファイル一覧", style = MaterialTheme.typography.titleSmall, color = MaterialTheme.colorScheme.primary)

                    files.forEach { file ->
                        val currentName = renameInputs[file] ?: file
                        Card(
                            modifier = Modifier.fillMaxWidth(),
                            colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant)
                        ) {
                            Column(
                                modifier = Modifier.padding(8.dp),
                                verticalArrangement = Arrangement.spacedBy(4.dp)
                            ) {
                                OutlinedTextField(
                                    value = currentName,
                                    onValueChange = { newVal -> renameInputs = renameInputs + (file to newVal) },
                                    label = { Text("ファイル名") },
                                    keyboardOptions = KeyboardOptions(imeAction = ImeAction.Done),
                                    modifier = Modifier.fillMaxWidth(),
                                    singleLine = true
                                )
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.End,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    if (currentName != file && currentName.isNotBlank()) {
                                        TextButton(onClick = {
                                            if (onRenameFile(selectedCategory, file, currentName)) {
                                                selectedFileName = currentName.trim()
                                            }
                                        }) { Text("名前を保存") }
                                    }

                                    if (files.size > 1) {
                                        TextButton(
                                            onClick = {
                                                onDeleteFile(selectedCategory, file)
                                                selectedFileName = files.firstOrNull { it != file } ?: "デフォルト"
                                            },
                                            colors = ButtonDefaults.textButtonColors(contentColor = MaterialTheme.colorScheme.error)
                                        ) { Text("削除") }
                                    }
                                }
                            }
                        }
                    }
                }
            },
            confirmButton = {
                Button(onClick = { showFileManageDialog = false }) { Text("閉じる") }
            }
        )
    }

    Column(modifier = Modifier.fillMaxSize().padding(16.dp)) {
        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
            Text("単語一覧", style = MaterialTheme.typography.headlineMedium)
            Row(horizontalArrangement = Arrangement.spacedBy(4.dp), verticalAlignment = Alignment.CenterVertically) {
                IconButton(onClick = { showSearch = !showSearch }) { Text("🔍", style = MaterialTheme.typography.titleLarge) }
                Button(onClick = onBack) { Text("戻る") }
            }
        }
        Spacer(modifier = Modifier.height(12.dp))

        Row(modifier = Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.SpaceBetween) {
            LazyRow(modifier = Modifier.weight(1f), horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                items(files) { file ->
                    val isSelected = (selectedFileName == file)
                    Button(
                        onClick = { selectedFileName = file },
                        colors = ButtonDefaults.buttonColors(
                            containerColor = if (isSelected) MaterialTheme.colorScheme.primary else Color.White,
                            contentColor = if (isSelected) MaterialTheme.colorScheme.onPrimary else Color.DarkGray
                        ),
                        border = if (!isSelected) BorderStroke(1.dp, Color.LightGray) else null
                    ) { Text(file) }
                }
            }
            OutlinedButton(onClick = { showFileManageDialog = true }) { Text("⚙️ 管理") }
        }

        Spacer(modifier = Modifier.height(8.dp))

        if (ranges.size > 1) {
            LazyRow(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                items(ranges, key = { it }) { range ->
                    FilterChip(
                        selected = selectedRange == range,
                        onClick = { selectedRange = range },
                        label = { Text(if (range == "すべて") "すべて (${fileWords.size}語)" else "$range 番") }
                    )
                }
            }
            Spacer(modifier = Modifier.height(8.dp))
        }

        LazyRow(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(4.dp)) {
            item { FilterChip(selected = sortOrder == "default", onClick = { sortOrder = "default" }, label = { Text("デフォルト順") }) }
            item { FilterChip(selected = sortOrder == "accuracy_desc", onClick = { sortOrder = "accuracy_desc" }, label = { Text("正答率が高い順") }) }
            item { FilterChip(selected = sortOrder == "accuracy_asc", onClick = { sortOrder = "accuracy_asc" }, label = { Text("正答率が低い順") }) }
            item { FilterChip(selected = sortOrder == "wrong_desc", onClick = { sortOrder = "wrong_desc" }, label = { Text("ミス回数が多い順") }) }
        }

        if (showSearch) {
            Spacer(modifier = Modifier.height(8.dp))
            OutlinedTextField(
                value = searchQuery,
                onValueChange = { searchQuery = it },
                label = { Text("検索") },
                keyboardOptions = KeyboardOptions(imeAction = ImeAction.Search),
                keyboardActions = KeyboardActions(onSearch = { focusManager.clearFocus() }),
                modifier = Modifier.fillMaxWidth(),
                singleLine = true
            )
        }

        Spacer(modifier = Modifier.height(10.dp))

        LazyColumn(modifier = Modifier.weight(1f).fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(6.dp)) {
            items(filteredWords, key = { "${it.category}_${it.fileName}_${it.id}" }) { word ->
                val key = "${word.category}_${word.fileName}_${word.id}"
                val cor = correctCounts[key] ?: 0
                val wro = wrongCounts[key] ?: 0
                val tot = cor + wro
                val acc = if (tot > 0) (cor * 100) / tot else 0

                Card(modifier = Modifier.fillMaxWidth()) {
                    Row(
                        modifier = Modifier.fillMaxWidth().padding(12.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Column(modifier = Modifier.weight(1f)) {
                            Text(text = "${word.id}. ${word.english}", style = MaterialTheme.typography.titleMedium)
                            Text(text = word.japanese, style = MaterialTheme.typography.bodySmall)
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = "正答率: $acc% (正解: ${cor}回 / ミス: ${wro}回)",
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.primary
                            )
                        }
                        Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                            IconButton(onClick = { onSpeak(word.english) }) { Text("🔊", style = MaterialTheme.typography.titleLarge) }
                            OutlinedButton(onClick = {
                                editingWord = word
                                editEnglish = word.english
                                editJapanese = word.japanese
                            }) { Text("編集") }

                            Button(
                                onClick = { onDeleteMultipleWords(listOf(word.id), selectedCategory, selectedFileName) },
                                colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.error)
                            ) { Text("削除") }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun TestScreen(
    wordList: List<Word>,
    wrongCounts: Map<String, Int>,
    lastWrongTimes: Map<String, Long>,
    category: String,
    fileName: String,
    startId: Int,
    endId: Int,
    isShuffled: Boolean,
    testScopeType: String,
    testMode: String,
    testSessionId: Int,
    onWrongAnswer: (Word) -> Unit,
    onCorrectAnswer: (Word) -> Unit,
    onUndoWrongAnswer: (Word) -> Unit,
    onUndoCorrectAnswer: (Word) -> Unit,
    onSpeak: (String) -> Unit,
    onBack: () -> Unit
) {
    val questions = remember(testSessionId) {
        val baseFileWords = wordList.filter { it.category == category && it.fileName == fileName }
        val filtered = when (testScopeType) {
            "today_wrong" -> {
                val todayStr = js("""
                    (function() {
                        const d = new Date();
                        const y = d.getFullYear();
                        const m = String(d.getMonth() + 1).padStart(2, '0');
                        const day = String(d.getDate()).padStart(2, '0');
                        return y + '-' + m + '-' + day;
                    })()
                """) as String
                baseFileWords.filter { word ->
                    val key = "${word.category}_${word.fileName}_${word.id}"
                    val time = lastWrongTimes[key] ?: 0L
                    if (time > 0L) {
                        val dateStr = js("""
                            (function(t) {
                                const d = new Date(t);
                                const y = d.getFullYear();
                                const m = String(d.getMonth() + 1).padStart(2, '0');
                                const day = String(d.getDate()).padStart(2, '0');
                                return y + '-' + m + '-' + day;
                            })(time)
                        """) as String
                        dateStr == todayStr
                    } else false
                }
            }
            "forgetting_curve" -> {
                val now = (js("Date.now()") as Number).toDouble()
                baseFileWords.filter { word ->
                    val key = "${word.category}_${word.fileName}_${word.id}"
                    val time = lastWrongTimes[key] ?: 0L
                    if (time > 0L) {
                        val hours = (now - time) / (1000.0 * 60.0 * 60.0)
                        hours >= 24.0
                    } else false
                }
            }
            else -> baseFileWords.filter { it.id in startId..endId }
        }

        if (isShuffled) filtered.shuffled() else filtered
    }

    var currentIndex by remember(testSessionId) { mutableStateOf(0) }
    var score by remember(testSessionId) { mutableStateOf(0) }
    var showAnswer by remember(currentIndex) { mutableStateOf(false) }
    var answeredChoice by remember(currentIndex) { mutableStateOf<String?>(null) }
    val history = remember(testSessionId) { mutableStateListOf<TestHistory>() }

    val choicesMap = remember(questions) {
        val baseFileWords = wordList.filter { it.category == category && it.fileName == fileName }
        questions.associate { currentWord ->
            val otherJapList = baseFileWords
                .filter { it.id != currentWord.id }
                .map { it.japanese }
                .distinct()
                .shuffled()
                .take(3)

            val dummyList = listOf("りんご", "バナナ", "オレンジ", "ペン").filter { it != currentWord.japanese }
            val finalWrong = (otherJapList + dummyList).distinct().take(3)

            val choiceList = (finalWrong + currentWord.japanese).shuffled()
            currentWord.id to choiceList
        }
    }

    val choices = if (questions.isNotEmpty() && currentIndex < questions.size) {
        val currentWord = questions[currentIndex]
        choicesMap[currentWord.id] ?: emptyList()
    } else {
        emptyList()
    }

    Column(
        modifier = Modifier.fillMaxSize().padding(24.dp),
        verticalArrangement = Arrangement.Center,
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        if (questions.isEmpty()) {
            val emptyMsg = when (testScopeType) {
                "today_wrong" -> "今日間違えた問題はありません！お見事です 🎉"
                "forgetting_curve" -> "現在、忘却曲線に基づく復習対象の問題はありません！素晴らしい記憶力です 🧠✨"
                else -> "この範囲に単語が登録されていません。"
            }
            Text(emptyMsg, style = MaterialTheme.typography.bodyLarge)
            Spacer(modifier = Modifier.height(16.dp))
            Button(onClick = onBack) { Text("戻る") }
        } else if (currentIndex < questions.size) {
            val currentWord = questions[currentIndex]

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text("問題 (${currentIndex + 1} / ${questions.size})", style = MaterialTheme.typography.titleMedium)

                    if (history.isNotEmpty()) {
                        OutlinedButton(
                            onClick = {
                                val last = history.removeAt(history.size - 1)
                                currentIndex = last.index
                                score = last.score
                                answeredChoice = null
                                if (last.wasCorrect) {
                                    onUndoCorrectAnswer(last.word)
                                } else {
                                    onUndoWrongAnswer(last.word)
                                }
                            },
                            contentPadding = PaddingValues(horizontal = 8.dp, vertical = 4.dp)
                        ) {
                            Text("⬅️ 1つ前に戻る")
                        }
                    }
                }

                OutlinedButton(onClick = onBack) { Text("途中で終了") }
            }
            Spacer(modifier = Modifier.height(16.dp))

            if (testMode == "card") {
                // めくり式カード
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(240.dp)
                        .pointerInput(showAnswer) {
                            if (!showAnswer) {
                                detectTapGestures(onTap = { showAnswer = true })
                            }
                        },
                    elevation = CardDefaults.cardElevation(8.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant)
                ) {
                    Box(modifier = Modifier.fillMaxSize().padding(24.dp), contentAlignment = Alignment.Center) {
                        Column(horizontalAlignment = Alignment.CenterHorizontally) {
                            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                Text(text = currentWord.english, style = MaterialTheme.typography.headlineLarge)
                                IconButton(onClick = { onSpeak(currentWord.english) }) { Text("🔊", style = MaterialTheme.typography.titleLarge) }
                            }

                            Spacer(modifier = Modifier.height(16.dp))
                            HorizontalDivider(modifier = Modifier.width(100.dp))
                            Spacer(modifier = Modifier.height(16.dp))

                            if (showAnswer) {
                                Text(
                                    text = currentWord.japanese,
                                    style = MaterialTheme.typography.headlineMedium,
                                    color = MaterialTheme.colorScheme.primary
                                )
                            } else {
                                Button(onClick = { showAnswer = true }) {
                                    Text("👆 タップして答えを見る")
                                }
                            }
                        }
                    }
                }

                Spacer(modifier = Modifier.height(24.dp))

                Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(16.dp)) {
                    Button(
                        onClick = {
                            history.add(TestHistory(currentIndex, score, currentWord, wasCorrect = false))
                            onWrongAnswer(currentWord)
                            currentIndex++
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.error),
                        modifier = Modifier.weight(1f).height(56.dp)
                    ) {
                        Text("❌ 不正解", style = MaterialTheme.typography.titleMedium)
                    }
                    Button(
                        onClick = {
                            history.add(TestHistory(currentIndex, score, currentWord, wasCorrect = true))
                            score++
                            onCorrectAnswer(currentWord)
                            currentIndex++
                        },
                        colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primary),
                        modifier = Modifier.weight(1f).height(56.dp)
                    ) {
                        Text("⭕ 正解", style = MaterialTheme.typography.titleMedium)
                    }
                }
            } else {
                // 4択クイズ形式
                Card(
                    modifier = Modifier.fillMaxWidth().height(120.dp),
                    elevation = CardDefaults.cardElevation(8.dp),
                    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant)
                ) {
                    Box(modifier = Modifier.fillMaxSize().padding(16.dp), contentAlignment = Alignment.Center) {
                        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                            Text(text = currentWord.english, style = MaterialTheme.typography.headlineLarge)
                            IconButton(onClick = { onSpeak(currentWord.english) }) { Text("🔊", style = MaterialTheme.typography.titleLarge) }
                        }
                    }
                }

                Spacer(modifier = Modifier.height(12.dp))

                if (answeredChoice == null) {
                    Text("正しい日本語の意味を選んでください", style = MaterialTheme.typography.bodyMedium, color = Color.Gray)
                    Spacer(modifier = Modifier.height(8.dp))

                    Column(verticalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
                        choices.forEach { choice ->
                            Button(
                                onClick = {
                                    val isCorrect = (choice == currentWord.japanese)
                                    answeredChoice = choice
                                    history.add(TestHistory(currentIndex, score, currentWord, wasCorrect = isCorrect))
                                    if (isCorrect) {
                                        score++
                                        onCorrectAnswer(currentWord)
                                    } else {
                                        onWrongAnswer(currentWord)
                                    }
                                },
                                modifier = Modifier.fillMaxWidth().height(48.dp),
                                colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primaryContainer, contentColor = MaterialTheme.colorScheme.onPrimaryContainer)
                            ) {
                                Text(choice, style = MaterialTheme.typography.bodyLarge)
                            }
                        }
                    }
                } else {
                    val isCorrectResult = (answeredChoice == currentWord.japanese)
                    val feedbackColor = if (isCorrectResult) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.error

                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Text(
                            text = if (isCorrectResult) "⭕ 正解！" else "❌ 残念…不正解",
                            style = MaterialTheme.typography.titleLarge,
                            color = feedbackColor
                        )
                        if (!isCorrectResult) {
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = "正解: 「${currentWord.japanese}」",
                                style = MaterialTheme.typography.bodyLarge,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                        }

                        Spacer(modifier = Modifier.height(16.dp))

                        Column(verticalArrangement = Arrangement.spacedBy(8.dp), modifier = Modifier.fillMaxWidth()) {
                            choices.forEach { choice ->
                                val buttonColor = when {
                                    choice == currentWord.japanese -> MaterialTheme.colorScheme.primary
                                    choice == answeredChoice -> MaterialTheme.colorScheme.error
                                    else -> MaterialTheme.colorScheme.surfaceVariant
                                }
                                val textColor = when {
                                    choice == currentWord.japanese || choice == answeredChoice -> Color.White
                                    else -> MaterialTheme.colorScheme.onSurface
                                }

                                Button(
                                    onClick = {},
                                    enabled = false,
                                    modifier = Modifier.fillMaxWidth().height(48.dp),
                                    colors = ButtonDefaults.buttonColors(
                                        disabledContainerColor = buttonColor,
                                        disabledContentColor = textColor
                                    )
                                ) {
                                    Text(choice, style = MaterialTheme.typography.bodyLarge)
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(16.dp))

                        Button(
                            onClick = {
                                answeredChoice = null
                                currentIndex++
                            },
                            modifier = Modifier.fillMaxWidth().height(52.dp)
                        ) {
                            Text("次へ進む ▶", style = MaterialTheme.typography.titleMedium)
                        }
                    }
                }
            }
        } else {
            Text("🎉 テスト終了！お疲れ様でした", style = MaterialTheme.typography.headlineMedium)
            Spacer(modifier = Modifier.height(16.dp))
            Text("正解数: $score / ${questions.size}", style = MaterialTheme.typography.titleLarge)
            Spacer(modifier = Modifier.height(24.dp))
            Button(onClick = onBack, modifier = Modifier.fillMaxWidth().height(56.dp)) {
                Text("テスト設定に戻る", style = MaterialTheme.typography.titleMedium)
            }
        }
    }
}
